2	import { useTranslation } from "react-i18next";
3	
4	import { Button } from "@/components/ui/button";
5	
6	import { cn } from "@/lib/utils";
7	
8	import { emptyEntry } from "@/components/QuestionnaireV2/renderer/inputs/withEntryAt";
9	import { QUESTION_TYPE_COMPONENTS } from "@/components/QuestionnaireV2/renderer/questionTypeRegistry";
10	import { sanitizeStylingClasses } from "@/components/QuestionnaireV2/renderer/sanitizeStylingClasses";
11	import {
12	  useQuestionEnabled,
13	  useQuestionErrors,
14	  useQuestionResponse,
15	} from "@/components/QuestionnaireV2/renderer/store";
16	
17	import type { Question } from "@/types/questionnaire/question";
18	
19	import { useFormChrome } from "./chrome";
20	import { useFormRenderer } from "./FormContext";
21	import { NoteControl } from "./NoteControl";
22	import { SectionCard } from "./SectionCard";
23	import { StructuredSlot } from "./StructuredSlot";
24	
25	export interface QuestionBlockProps {
26	  question: Question;
27	  parentId: string | null;
28	  index: number;
29	  siblingCount: number;
30	  depth: number;
31	  /** Dotted ordinal matching the tree nav (e.g. "8." or "7.1."). */
32	  number?: string;
33	}
34	
35	/**
36	 * One node of the questionnaire tree on the one-scroll canvas — the full
37	 * renderer's counterpart to the old paginated QuestionField. Same response
38	 * semantics (single-entry vs positional repeats, chip inputs, structured
39	 * slot, sanitized styling), new layout, plus the two canvas seams: chrome
40	 * wrapping and `revealHidden`/`inert` handling from the form context.
41	 */
42	export function QuestionBlock(props: QuestionBlockProps) {
43	  const { question, depth, number } = props;
44	  const { mode, revealHidden } = useFormRenderer();
45	  const { QuestionShell } = useFormChrome();
46	  const enabled = useQuestionEnabled(question);
47	
48	  const hiddenByLogic = !enabled && question.disabled_display !== "protected";
49	  if (hiddenByLogic && !revealHidden) return null;
50	
51	  const disabled = mode === "readonly" || question.read_only === true;
52	  const effectiveDisabled = disabled || !enabled;
53	
54	  const wrap = (children: React.ReactNode) =>
55	    QuestionShell ? (
56	      <QuestionShell {...props} hiddenByLogic={hiddenByLogic}>
57	        {children}
58	      </QuestionShell>
59	    ) : (
60	      children
61	    );
62	
63	  if (question.type === "group") {
64	    return wrap(
65	      <SectionCard
66	        question={question}
67	        depth={depth}
68	        disabled={effectiveDisabled}
69	        number={number}
70	      />,
71	    );
72	  }
73	
74	  return wrap(
75	    <LeafBlock
76	      question={question}
77	      depth={depth}
78	      number={number}
79	      effectiveDisabled={effectiveDisabled}
80	    />,
81	  );
82	}
83	
84	/**
85	 * The non-group body — a separate component so the response and error
86	 * store subscriptions only exist for questions that actually record
87	 * answers (groups returned above without ever mounting them).
88	 */
89	function LeafBlock({
90	  question,
91	  depth,
92	  number,
